module.exports = async (args) => {
  const log = (m) => args.jobLog(`[Master AV1] ${m}\n`);
  const globals = (args.userVariables && args.userVariables.global) || {};
  const ff = args.variables && args.variables.ffmpegCommand;
  if (!ff || !Array.isArray(ff.streams)) throw new Error('FFmpeg command is not initialized');
  const input = args.inputFileObj || {};
  const ffprobeStreams = (input.ffProbeData && input.ffProbeData.streams) || [];
  const base = String(input._id || '').split('/').pop().replace(/\.[^.]+$/, '');
  let videoBitrate = 0;
  const miTracks = (input.mediaInfo && input.mediaInfo.track) || [];
  for (const t of miTracks) { if (String(t['@type'] || '').toLowerCase() === 'video' && Number(t.BitRate) > 0) videoBitrate = Math.max(videoBitrate, Number(t.BitRate)); }
  if (!videoBitrate) { for (const s of ffprobeStreams) { if (s.codec_type === 'video' && Number(s.bit_rate) > 0) videoBitrate = Math.max(videoBitrate, Number(s.bit_rate)); } }
  let qual = 20;
  if (videoBitrate > 0 && videoBitrate < 5000000) qual = 23; else if (videoBitrate > 0 && videoBitrate < 10000000) qual = 22; else if (videoBitrate > 0 && videoBitrate < 20000000) qual = 21;
  args.variables.user = args.variables.user || {};
  args.variables.user.qual = String(qual);
  args.variables.user.sourceVideoBitrateMbps = videoBitrate ? (videoBitrate / 1000000).toFixed(2) : 'unknown';
  log(`Source video bitrate: ${args.variables.user.sourceVideoBitrateMbps} Mbps -> Q${qual}`);
  const probeText = JSON.stringify(input.ffProbeData || {}).toLowerCase();
  const isDolbyVision = probeText.includes('dovi configuration record') || probeText.includes('dolby vision') || probeText.includes('dvhe') || probeText.includes('dvh1');
  args.variables.user.dolbyVision = isDolbyVision ? 'true' : 'false';
  if (isDolbyVision) log('Dolby Vision detected: video transcode will be skipped to preserve DV.');
  const a2to3 = {en:'eng',fr:'fre',de:'ger',es:'spa',it:'ita',ja:'jpn',ko:'kor',zh:'chi',pt:'por',ru:'rus',nl:'dut',sv:'swe',no:'nor',da:'dan',fi:'fin',pl:'pol',cs:'cze',tr:'tur',ar:'ara',he:'heb',hi:'hin',th:'tha',vi:'vie',id:'ind',ms:'may',uk:'ukr',ro:'rum',hu:'hun',el:'gre',bg:'bul',hr:'hrv',sr:'srp',sk:'slo',sl:'slv',is:'ice',et:'est',lv:'lav',lt:'lit',fa:'per',bn:'ben',ta:'tam',te:'tel',ml:'mal',mr:'mar',ur:'urd',ca:'cat',eu:'baq',gl:'glg'};
  const nameTo3 = {english:'eng',french:'fre',german:'ger',spanish:'spa',italian:'ita',japanese:'jpn',korean:'kor',chinese:'chi',portuguese:'por',russian:'rus',dutch:'dut',swedish:'swe',norwegian:'nor',danish:'dan',finnish:'fin',polish:'pol',czech:'cze',turkish:'tur',arabic:'ara',hebrew:'heb',hindi:'hin',thai:'tha',vietnamese:'vie',indonesian:'ind',malay:'may',ukrainian:'ukr',romanian:'rum',hungarian:'hun',greek:'gre',bulgarian:'bul'};
  const normUrl = (u) => { u = String(u || '').trim(); if (!u) return ''; if (!/^https?:\/\//i.test(u)) u = `http://${u}`; return u.replace(/\/+$/, ''); };
  const headers = (key) => ({'X-Api-Key': String(key || ''), Accept:'application/json'});
  let originalLang = '';
  try {
    const ru = normUrl(globals.radarr_url), rk = String(globals.radarr_api_key || '');
    if (ru && rk) { const r = await args.deps.axios({method:'get',url:`${ru}/api/v3/parse?title=${encodeURIComponent(base)}`,headers:headers(rk)}); const name = String(r?.data?.movie?.originalLanguage?.name || '').toLowerCase(); if (name) originalLang = nameTo3[name] || ''; if (originalLang) log(`Original language from Radarr: ${name} (${originalLang})`); }
  } catch (e) { log(`Radarr original-language lookup did not resolve: ${e.message || e}`); }
  try {
    if (!originalLang) { const su = normUrl(globals.sonarr_url), sk = String(globals.sonarr_api_key || ''), tk = String(globals.tmdb_api_key || ''); if (su && sk) { const s = await args.deps.axios({method:'get',url:`${su}/api/v3/parse?title=${encodeURIComponent(base)}`,headers:headers(sk)}); const imdb = String(s?.data?.series?.imdbId || ''); if (imdb && tk) { const t = await args.deps.axios({method:'get',url:`https://api.themoviedb.org/3/find/${encodeURIComponent(imdb)}`,params:{api_key:tk,language:'en-US',external_source:'imdb_id'}}); const item = (t?.data?.tv_results || [])[0] || (t?.data?.movie_results || [])[0]; const a2 = String(item?.original_language || '').toLowerCase(); originalLang = a2to3[a2] || ''; if (originalLang) log(`Original language from Sonarr/TMDB: ${a2} (${originalLang})`); } } }
  } catch (e) { log(`Sonarr/TMDB original-language lookup did not resolve: ${e.message || e}`); }
  args.variables.user.originalLanguage = originalLang || 'unknown';
  const normalizeLang = (v) => { const s = String(v || 'und').toLowerCase().replace('_','-'); if (s === 'en' || s.startsWith('en-')) return 'eng'; if (a2to3[s]) return a2to3[s]; return s.slice(0,3); };
  const isCommentary = (s) => /commentary|audio description|descriptive/i.test(String(s?.tags?.title || ''));
  const audio = ff.streams.filter(s => s.codec_type === 'audio' && !s.removed);
  const rank = (s) => { const codec = String(s.codec_name || '').toLowerCase(); const profile = String(s.profile || '').toLowerCase(); let score = 0; if (codec === 'truehd') score += 10000; else if (codec === 'flac') score += 9500; else if (codec === 'dts' && /ma|master/i.test(profile)) score += 9000; else if (codec === 'dts') score += 8000; else if (codec === 'eac3') score += 7000; else if (codec === 'ac3') score += 6000; else if (codec === 'opus') score += 5500; else if (codec === 'aac') score += 5000; score += Number(s.channels || 0) * 100; score += Math.min(Number(s.bit_rate || 0) / 100000, 500); if (!isCommentary(s)) score += 20000; return score; };
  if (originalLang) {
    const desired = new Set(['eng', originalLang]), groups = {};
    for (const s of audio) { const lang = normalizeLang(s?.tags?.language); if (desired.has(lang)) (groups[lang] ||= []).push(s); }
    if (!groups[originalLang] || !groups[originalLang].length) { const und = audio.filter(s => normalizeLang(s?.tags?.language) === 'und'); if (und.length) groups[originalLang] = und; }
    const keep = new Set();
    for (const lang of desired) { const list = (groups[lang] || []).sort((a,b) => rank(b)-rank(a)); if (list[0]) keep.add(list[0]); }
    if (keep.size === 0 && audio.length) { keep.add([...audio].sort((a,b) => rank(b)-rank(a))[0]); log('No desired-language audio was found; preserved the best audio stream as a safety fallback.'); }
    for (const s of audio) if (!keep.has(s)) s.removed = true;
    log(`Audio cleanup: kept ${keep.size} best track(s) for original + English; audio codecs are stream-copied.`);
  } else log('Original language could not be determined safely; ALL audio is preserved to avoid destructive guessing.');
  let keptSubs = 0, removedSubs = 0;
  for (const s of ff.streams.filter(s => s.codec_type === 'subtitle' && !s.removed)) { const lang = normalizeLang(s?.tags?.language); const title = String(s?.tags?.title || ''); const forced = s?.disposition?.forced === 1 || s?.disposition?.forced === true || /\bforced\b/i.test(title); if (!(lang === 'eng' || forced)) { s.removed = true; removedSubs++; } else keptSubs++; }
  log(`Subtitle cleanup: kept ${keptSubs} English/forced subtitle stream(s), removed ${removedSubs}.`);
  return {outputFileObj: args.inputFileObj, outputNumber: isDolbyVision ? 2 : 1, variables: args.variables};
};
